#!/usr/bin/env bash
set -euo pipefail
command -v node >/dev/null 2>&1 || { echo 'Node.js is required.' >&2; exit 1; }
node <<'AF_BIOLOGY_CARDS_NODE'
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const files={"src/app/biology/page.tsx": "import Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { lessons } from '@/lib/biology/lessons';\n\nexport const metadata = { title: 'Biology simulations | A-Factor STEM Studio' };\n\nconst TOPIC_STYLE: Record<string, { icon: string; category: string }> = {\n  'skeletal-system': { icon: '\ud83e\uddb4', category: 'Human biology' },\n  cells: { icon: '\ud83d\udd2c', category: 'Cell biology' },\n  mitosis: { icon: '\ud83e\uddec', category: 'Cell division' },\n  meiosis: { icon: '\ud83e\uddec', category: 'Cell division' },\n  transpiration: { icon: '\ud83c\udf3f', category: 'Plant biology' },\n  classification: { icon: '\ud83d\uddc2\ufe0f', category: 'Classification' },\n  'life-processes': { icon: '\ud83c\udf31', category: 'Foundations' },\n};\n\nexport default function BiologyHub() {\n  const cards = [\n    { slug: 'skeletal-system', title: 'Human skeletal system', intro: 'Explore major bones, axial and appendicular divisions, and identification challenges.' },\n    ...Object.entries(lessons).map(([slug, lesson]) => ({ slug, title: lesson.title, intro: lesson.intro })),\n  ];\n\n  return (\n    <div className=\"min-h-screen bg-gray-50 text-gray-900\">\n      <AppHeader />\n      <main className=\"mx-auto max-w-7xl px-4 py-8 sm:px-6\">\n        <p className=\"text-sm font-semibold text-teal-700\">A-Factor STEM Studio \u00b7 Biology</p>\n        <h1 className=\"mt-2 text-3xl font-semibold\">Explore living systems</h1>\n        <p className=\"my-4 max-w-2xl text-sm leading-7 text-gray-600\">\n          Interactive models, classroom challenges, teacher guidance and student practice. Expand any activity for a classroom demonstration.\n        </p>\n        <div className=\"grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4\">\n          {cards.map(card => {\n            const style = TOPIC_STYLE[card.slug] ?? { icon: '\ud83d\udd2c', category: 'Biology' };\n            return (\n              <div key={card.slug} className=\"group relative overflow-hidden rounded-2xl border border-gray-200 bg-white transition hover:border-indigo-300 hover:shadow-md focus-within:border-indigo-300 focus-within:shadow-md\">\n                <div className=\"pointer-events-none absolute right-3 top-3 flex items-center gap-1\">\n                  <span aria-hidden=\"true\" className=\"h-1.5 w-1.5 rounded-full bg-emerald-500\" />\n                  <span className=\"text-[10px] font-medium text-emerald-600\">Live</span>\n                </div>\n                <Link href={'/biology/' + card.slug} className=\"block h-full rounded-2xl focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600\">\n                  <div className=\"p-5\">\n                    <div className=\"mb-3 flex items-center gap-2 pr-12\">\n                      <span aria-hidden=\"true\" className=\"text-2xl\">{style.icon}</span>\n                      <span className=\"text-[10px] font-medium uppercase tracking-wide text-gray-400\">{style.category}</span>\n                    </div>\n                    <h2 className=\"mb-1.5 text-sm font-semibold text-gray-900 transition group-hover:text-indigo-700\">{card.title}</h2>\n                    <p className=\"mb-3 text-xs leading-relaxed text-gray-500\">{card.intro}</p>\n                    <div className=\"flex flex-wrap gap-1.5\">\n                      <span className=\"rounded-full bg-indigo-100 px-2 py-0.5 text-[10px] font-medium text-indigo-700\">Interactive</span>\n                      <span className=\"rounded-full bg-emerald-100 px-2 py-0.5 text-[10px] font-medium text-emerald-700\">Teacher &amp; student</span>\n                    </div>\n                  </div>\n                </Link>\n              </div>\n            );\n          })}\n        </div>\n      </main>\n    </div>\n  );\n}\n"},expected={"src/app/biology/page.tsx": "042fd646135168cb2847e464fd63a515d782e225f51912b08ff11af562d39c83"};
const root=process.cwd();
function stop(message){console.error('Stopped: '+message+' No application files changed.');process.exit(1);}
if(!fs.existsSync('package.json')||!fs.existsSync('src/app/simulations/oscillations/page.tsx'))stop('Run this patch from your A-Factor project root.');
const normalize=s=>s.replace(/\r\n/g,'\n');
const hash=s=>crypto.createHash('sha256').update(normalize(s)).digest('hex');
function safe(file){let current=root;for(const part of file.split('/')){current=path.join(current,part);try{if(fs.lstatSync(current).isSymbolicLink())stop('Symbolic link at '+file);}catch(e){if(e.code!=='ENOENT')throw e;}}}
for(const file of [...Object.keys(files),'.stem-tutor-backups'])safe(file);
const changed=[],conflicts=[];
for(const [file,content] of Object.entries(files)){
 const current=fs.existsSync(file)?fs.readFileSync(file,'utf8'):null;
 if(current!==null&&normalize(current)===normalize(content))continue;
 if((current===null&&expected[file]!==null)||(current!==null&&(expected[file]===null||hash(current)!==expected[file])))conflicts.push(file);
 else changed.push(file);
}
if(conflicts.length)stop('These files differ from the project state after the Biology topics expansion. Keep your edits and request a refreshed patch:\n'+conflicts.join('\n'));
if(!changed.length){console.log('The matching Biology topic cards are already installed.');process.exit(0);}
fs.mkdirSync('.stem-tutor-backups',{recursive:true});const backup=fs.mkdtempSync('.stem-tutor-backups/biology-cards-'),originals=new Map();
for(const file of changed){const old=fs.existsSync(file)?fs.readFileSync(file):null;originals.set(file,old);if(old!==null){const copy=path.join(backup,file);fs.mkdirSync(path.dirname(copy),{recursive:true});fs.writeFileSync(copy,old);}}
fs.writeFileSync(path.join(backup,'manifest.json'),JSON.stringify(changed.map(file=>({file,existed:originals.get(file)!==null})),null,2));
try{for(const file of changed){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,files[file],'utf8');}}catch(error){for(const [file,old]of originals){if(old===null){if(fs.existsSync(file))fs.unlinkSync(file);}else fs.writeFileSync(file,old);}console.error('Write failed; originals restored: '+error.message);process.exit(1);}
console.log('Installed '+changed.length+' files: Biology catalogue cards matching the existing simulation card style.');
console.log('Backup: '+backup);
console.log('No new packages or API keys are needed. Existing topic routes and the subject dropdown are preserved.');
console.log('Restart your dev server: npm run dev');
console.log('Checks: npm run build');
AF_BIOLOGY_CARDS_NODE
